// AUTO-GENERATED by scripts/build-bible-v205.ts — do not edit by hand.
// Words: Jonathan's canonical commentary txt. Structure: his Notion pages.
import type { V205BookData } from '../types';

export const DATA: V205BookData = {
  book: "1 Peter",
  display: "First Peter",
  chapters: {
    "1": {"chapter":1,"intro":[{"kind":"para","text":"Peter was jailed in AD 41-44 (the book of Acts records these events). He writes this letter in AD 62-63. He is then killed not too long after this in AD 64-67. This letter allows Peter to leave quite a legacy and hope to those that experience trials and burdens."},{"kind":"para","text":"Believe it or not, assurance of salvation is a common issue with a lot of believers. There’s a lot of doctrine which touches specifically on this issue, and it will be mentioned quite a bit in this chapter of 1 Peter. The reason a lot of people have a hard time with their eternal security is because they will face suffering or conflict in their faith. They have the assumption that if they face trials or burdens, then there must be something wrong with their salvation. This simply isn’t true. Suffering actually should be producing the opposite of insecurity. It should be producing JOY! That’s what we need to focus on when we read through these verses. How does suffering lead the believer to joy?"},{"kind":"para","text":"The books of 1, 2 Peter, 1, 2, and 3 John, and 1, and 2 Timothy all focus on the same issue, which is the denial of Christ in the church. 1, 2, and 3 John warn about those people in the church who would deny Christ, and how to look out for that in yourself. 1, and 2 Timothy speak to the leadership around people who are anti-Christ, and how to maintain focus on Him. 1, and 2 Peter speak about how we can have joy in ministry while people are trying to reject your ministry for Christ."}],"previously":[],"outline":[],"sections":[{"start":1,"end":2,"title":"Greeting","entries":[{"start":1,"end":1,"blocks":[{"kind":"para","text":"Peter’s name literally means “stone.” He took on the persona of Peter after Jesus changed his name from Simon to Simon Peter (or Cephas rather)."},{"kind":"scripture","text":"And he brought him to Jesus. And when Jesus beheld him, he said, Thou art Simon the son of Jona: thou shalt be called Cephas, which is by interpretation, A stone.","ref":"John 1:42"},{"kind":"para","text":"He’s experienced quite a bit of trial and suffering already for Christ, being thrown in prison multiple times, beaten, mocked, scourged, persecuted, and continuously derailed. If anyone has the right mentality and outlook on Christian suffering, and who is able to give the best advice for such times as this, it would be Peter."},{"kind":"para","text":"You don’t want to take the advice of suffering from someone who has never suffered before. You certainly don’t want to take the advice of someone who doesn’t even know what suffering really is. They may have an idea, or a theory, but that will not ultimately help you when you need it the most. They have never overcome the trials and burdens. They have never faced the issues that you are soon to face or have already faced. They have no idea how to successfully turn to the Lord in the matter."}]},{"start":2,"end":2,"blocks":[{"kind":"para","text":"Peter doesn’t hold anything back here. He gets really theological and doctrinal just in the second verse. He explains his position to those who are to read this letter. He wants them to understand where he’s coming from and why he has the authority to say the words he is saying through this letter. It’s not just because he was with Christ or knew Christ. It was because he continued the preaching and teaching of Christ. It was because he was set apart for the work in which God called him too. It was because he was obedient to the sacrifice that Jesus made for him."},{"kind":"para","text":"Peter was more than a fisherman. He was a leader in God’s Word, and he was a learner of it still, continually. This is a letter of what he learned. Not only so, but when we are sanctified the first time into salvation (that’s of the putting off of the flesh and putting on Jesus Christ), we are in a new life. But when Peter says that he is “sanctified” of the Spirit, he is referring to the maturing that the Spirit provides after salvation. We become more pure as the Spirit resides in us. If we are not becoming more pure through God’s Spirit, there is something wrong with our first sanctification. This sanctification process is called “Progressive Sanctification.” We will never have “Ultimate Sanctification” until we are dead, and so we progressively work out our faith until then."}]}]},{"start":3,"end":12,"title":"Christ Owns Us","entries":[{"start":3,"end":3,"blocks":[{"kind":"para","text":"Peter is taking this first part of the letter to show the importance of remembering that Christ has begotten (taken ownership of) us, proving His mercy, giving us a hope that is alive because He rose from the dead, and that gives us ample reason enough to bless God! If we cannot bless God, that’s because we have not been blessed by God."}]},{"start":4,"end":4,"blocks":[{"kind":"para","text":"Peter is claiming a promise here. Our home in heaven, and our guarantee of eternity, is incorruptible, it’s undefiled, and never fades away. That word “reserved” means “guarded.” No matter how far gone God may seem, or how far gone our faith seems to have dwindled, God’s promise of our inheritance in eternity will still stand forever, because it’s “reserved” in Heaven specifically for us. Not just for Peter. Not just for the Apostles or “saints.” But for those that are “elect” (another term for Saint) according to the foreknowledge of God. The elect being anyone who receives Christ, of course."},{"kind":"scripture","text":"In whom also we have obtained an inheritance, being predestinated according to the purpose of him who worketh all things after the counsel of his own will: That we should be to the praise of his glory, who first trusted in Christ. In whom ye also trusted, after that ye heard the word of truth, the gospel of your salvation: in whom also after that ye believed, ye were sealed with that holy Spirit of promise,","ref":"Ephesians 1:11-13"},{"kind":"para","text":"Peter is using this opportunity to write to the persecuted Christians about what their focus must remain on. Not on the trial, but on the promises of God."}]},{"start":5,"end":5,"blocks":[{"kind":"para","text":"We are also promised to be “kept” as Peter determines here. We don’t have to worry about whether or not Jesus desires to keep us because He has already promised that He has and will!"},{"kind":"scripture","text":"While I was with them in the world, I kept them in thy name: those that thou gavest me I have kept, and none of them is lost, but the son of perdition; that the scripture might be fulfilled.","ref":"John 17:12"},{"kind":"para","text":"Paul puts it this way,"},{"kind":"scripture","text":"Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:","ref":"Philippians 1:6"}]},{"start":6,"end":6,"blocks":[{"kind":"para","text":"We may be in heaviness through a “season” of difficulty, but Peter reminds us that we can “greatly rejoice” because of God’s promise to keep us. That’s the theme that Peter focuses on here, “joy” or “rejoicing!” Through every trait that man can give, it’s usually filled with anger or bitterness. Through the trait that God gives, it’s forgiveness and joy! Even during the harshest and heaviest times of our lives, we are commanded and made (in God’s image) to receive joy. Even Jesus, in the hardest time of His life, had His joy full!"},{"kind":"scripture","text":"Looking unto Jesus the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of God.","ref":"Hebrews 12:2"},{"kind":"para","text":"That’s not a very joyous occasion, yet that is what God’s Spirit does. If we are lacking joy, we are lacking God’s Spirit; that is the bottom line. There’s no way to sugarcoat it. We need to be filled with God’s Spirit if we are going to have joy in anything that we do. You might think to yourself, “Well, yeah, I’ve already received God’s Spirit the day I was saved!” Great! But when was the last time you were RE-filled with God’s Spirit? After the Spirit came during Pentecost, we read this about the disciples and the Holy Spirit…"},{"kind":"scripture","text":"And when they had prayed, the place was shaken where they were assembled together; and they were all filled with the Holy Ghost, and they spake the word of God with boldness.","ref":"Acts 4:31"},{"kind":"para","text":"It seems that if anyone is a professional on the matter of being “refilled” by God’s Spirit, it would be Peter who was continuously filled and provenly so through the entire book of Acts. I do believe this is why Christians make some grave mistakes in their faith and walk. It’s because they haven’t been refilled by the Spirit of God. So how do we become refilled with God’s Spirit? Through God’s Word, of course!"},{"kind":"scripture","text":"Sanctify them through thy truth: thy word is truth.","ref":"John 17:17"},{"kind":"para","text":"The word “sanctify” means “to purify” or “make holy.” We can be filled repeatedly by God’s Spirit through the washing of His Word! This way, when persecution arises, we have a fresh look and take on the issue at hand."}]},{"start":7,"end":7,"blocks":[{"kind":"para","text":"“Precious” is a very important word to Peter. In fact, it might suffice for us to underline it every time Peter mentions it. There are certain things he refers to as precious. This particular verse illustrates that the most precious thing we can have in this life is our faith. It’s more precious than all of the material wealth we can gain. It’s worth giving up everything for."},{"kind":"para","text":"That is what Peter did after all. He gave up a life of fishing and making a decent income for a life of preaching and teaching with no source of income. No doubt, there would be time for him to make money in certain areas so that he may provide for himself and his household, but God took care of all his needs because Peter treated his faith as “precious.” It was important to Peter that he keep his faith. He knows what it’s like to lose it…"},{"kind":"scripture","text":"And Peter went out, and wept bitterly.","ref":"Luke 22:62"},{"kind":"para","text":"Peter understands that faith will be tried…"},{"kind":"scripture","text":"And to him they agreed: and when they had called the apostles, and beaten them, they commanded that they should not speak in the name of Jesus, and let them go.","ref":"Acts 5:40"},{"kind":"para","text":"Peter understood that even through this there would be reason to rejoice…"},{"kind":"scripture","text":"And they departed from the presence of the council, rejoicing that they were counted worthy to suffer shame for his name.","ref":"Acts 5:41"},{"kind":"para","text":"Look at his next verse…"}]},{"start":8,"end":8,"blocks":[{"kind":"para","text":"Peter saw Jesus, even the resurrected Jesus. He had reason to believe and love Jesus because He was right there with Him. We have not seen Jesus, yet Peter’s faith and testimony are bringing our belief to Christ. This letter is an eyewitness testament to endure trials because Jesus is very real. He’s not just an idea, or just a teacher. He’s God in the flesh, who literally came to Earth, walked with Peter, talked with Peter, and worked ministry with Peter. Peter was a blessed man for his work with Christ, and Peter is reminding these other believers how blessed they are because they still believe and love Christ!"},{"kind":"scripture","text":"Jesus saith unto him, Thomas, because thou hast seen me, thou hast believed: blessed are they that have not seen, and yet have believed.","ref":"John 20:29"},{"kind":"para","text":"We have the upper hand here. Our faith is not based on physical evidence, but spiritual ones!"},{"kind":"scripture","text":"Now faith is the substance of things hoped for, the evidence of things not seen.","ref":"Hebrews 1:1"},{"kind":"para","text":"Our faith relies on the proof of things that we have not seen, and it relies on the proof of God’s Word…"},{"kind":"scripture","text":"How then shall they call on him in whom they have not believed? and how shall they believe in him of whom they have not heard? and how shall they hear without a preacher?","ref":"Romans 10:14"}]},{"start":9,"end":11,"blocks":[{"kind":"para","text":"The Old Testament prophets were promised a Savior, we have received Him because He lives today! He is the end of our faith."},{"kind":"scripture","text":"Looking unto Jesus the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of God.","ref":"Hebrews 12:2"},{"kind":"para","text":"The prophets foretold the events that would lead up to Christ’s persecution and death, followed by His resurrection and salvation. This is what the prophets looked forward to and kept their hope in. This is what can ultimately bring us hope today."},{"kind":"para","text":"When we think back on the fact that Christ died for us, when He didn’t have to, for the sins we have committed, and still have yet to commit, it brings everything we ever do or have ever done into proper perspective. It renews our Spirit to remember Christ’s death."}]},{"start":12,"end":12,"blocks":[{"kind":"para","text":"In other words, Peter is saying, “We (the apostles) are preaching the same things that the prophets did!” Now, I find this part very interesting, “…which things the angels desire to look into…” The angels are reportedly “God’s Messengers.” In other words, they do and say what God tells them to. If they are told to talk to someone, they go and talk to someone, and it has been reported several times over, including, and especially to John in the book of Revelation."},{"kind":"scripture","text":"And I fell at his feet to worship him. And he said unto me, See thou do it not: I am thy fellowservant, and of thy brethren that have the testimony of Jesus: worship God: for the testimony of Jesus is the spirit of prophecy.","ref":"Revelation 19:10"},{"kind":"para","text":"The angels could easily report Christ’s salvation and resurrection without even thinking twice about it. In fact, Peter says they desire to do it for the glory of God. They are, no doubt, looking at us who are the benefactors of this great salvation and wondering, “Why aren’t they telling people? We will gladly go and tell people the gospel! We are God’s messengers! It’s literally our job!” Yet, God wants us to have a desire to do so. He doesn’t want the angels to do it on our behalf, because the angels (though rejoicing over salvation and over Christ’s sacrifice)…"},{"kind":"scripture","text":"Likewise, I say unto you, there is joy in the presence of the angels of God over one sinner that repenteth.","ref":"Luke 15:10"},{"kind":"para","text":"…the angels don’t get to partake in Christ’s salvation. Only we do. And yet we have a harder time telling others about it. Peter is putting a slight emphasis on continuing through faith and preaching, even though people are evil and wicked. We are to continue to love and preach the Word of God to any and all that would listen because it could mean the saving of souls. We should be as (like the angels) desirous to be God’s messengers…"}]}]},{"start":13,"end":25,"title":"Called To Be Holy","entries":[{"start":13,"end":13,"blocks":[{"kind":"para","text":"“Get prepared,” Peter says. “Gird up the loins of your mind.” It’s a figure of speech. It’s like telling much of our generation today to “pull your pants up and put on a belt” because their pants are below their waist and they are walking around like penguins. Having your pants that low interferes with how you move. Peter wants us to “gird up” our minds so we are able to have hope and grace until the return of Jesus Christ. Why should we have hope? Because our hopes rest upon the resurrection of Jesus Christ."}]},{"start":14,"end":14,"blocks":[{"kind":"para","text":"We must not just listen to God’s Word, but obey God’s Word. That’s the key part of God’s Word: obedience. Obedience. That’s where ultimate joy comes from. Doing what God has commanded."}]},{"start":15,"end":15,"blocks":[{"kind":"para","text":"If we aren’t careful, we can assume holiness to be something which it isn’t. We might assume it to be unreachable and perfect. We might assume it to be pious and boisterous. We might assume it to be headstrong and prideful (even arrogant because you might think you are better than others). You might assume it to mean you cannot enjoy this life because it is not holy enough for you. God desires that we enjoy this life and have fun! Not in a sinful way, of course, but in a Godly fashion where we can rejoice and have joy, especially because the days will get long and hard."},{"kind":"para","text":"Someone once said, “Holiness is to the spiritual life what health is to the physical life.” In order to enjoy life, we must live holy lives. We must be exercising our holiness so we can find joy in everything we do. If you are not finding joy in being holy, you are not being holy."}]},{"start":16,"end":16,"blocks":[{"kind":"para","text":"Of course, we cannot obtain God’s holiness. He is perfect and sinless. We are neither… We are to be content and complete through God’s will and work. It’s not about our work or desires, but about His work and desires. Basking in His holiness is to release our efforts so that we can enjoy His."}]},{"start":17,"end":17,"blocks":[{"kind":"para","text":"God’s judgments are fair judgments. They have nothing to do with how proud and amazing we are, or how ignorant and fallible we are. Because we understand that God judges us, we should not bring us into “fear” in the sense that we are walking on eggshells in everything we do. But it should make us “sober-minded.” This is something that Peter will mention later, but it’s certainly an important aspect of living in holiness. We get to instinctively know right from wrong because God has revealed His Spirit and Will through His Word to us."}]},{"start":18,"end":19,"blocks":[{"kind":"para","text":"Peter uses “silver and gold” as an analogy again. He knows and understands that we place real value in material objects, when those values don’t even come close to comparing what is really valuable. He has said that our faith was valuable, now he says that Christ’s blood is valuable. He uses the term “precious” again. Christ’s blood gives value to our faith. They are both equally as precious, yet you can’t have one without the other. Christ’s blood should be looked at as no different than precious. Peter gives a very precise word for how we are to look at faith and Christ’s sacrifice."}]},{"start":20,"end":20,"blocks":[{"kind":"para","text":"No doubt, I won’t have to speak about the predestination and foreknowledge of God, but a few Bible verses do come to mind right off the bat here…"},{"kind":"scripture","text":"And now, O Father, glorify thou me with thine own self with the glory which I had with thee before the world was.","ref":"John 17:5"},{"kind":"scripture","text":"Father, I will that they also, whom thou hast given me, be with me where I am; that they may behold my glory, which thou hast given me: for thou lovedst me before the foundation of the world.","ref":"John 17:24"},{"kind":"para","text":"I can talk about this topic more through the book of Revelation. Jesus is obviously saying that He was with God before all of these events unfolded. Peter understood that Jesus is as God is… Omniscient… Scofield said, “As foreknowledge extends to all events, it includes all that is embraced in election, foreordination, and predestination. Election is, therefore, according to foreknowledge, and foreknowledge is according to election, meaning that both are in perfect agreement.”"},{"kind":"para","text":"God knows who will be saved, but that does not change His heart for those that won’t be. He doesn’t desire that any should perish, and because of this, Christ was foreordained before the foundation of the world, so that as many as will believe in His name will be saved. I also find it interesting that Peter says “…in these last times…” The Apostles talked a lot about living in the last days. They believed we were already living in it. Once the Holy Spirit came, we were then transitioned into “the last days…” We have been living in the “last days” for quite some time. These aren’t the tribulation days, these are the last days, until Christ returns again."}]},{"start":21,"end":21,"blocks":[{"kind":"para","text":"Once again, Peter refocuses our minds back on Christ’s resurrection. That is an important focus for the believers to have. Especially if we are living in the last days. We have reason to hope and rejoice because of this. Last time he said we must have “grace and hope,” but now he tells us to have “faith and hope.” Hope being the key word to Peter."}]},{"start":22,"end":23,"blocks":[{"kind":"para","text":"Brining it back to God’s Word, refreshing us. Peter reminds us that it is through His Word that we are purified, and it allows us to show love to others based on the love we have been given. If we cannot love others properly, we have not been loved properly. If we have not been loved properly, it is because we have not had the Spirit guide us through truth like this verse emphasizes. We aren’t just told to “love” either. We are told to love “fervently” with a pure heart. And of course, the only way we can truly love and have love is through our salvation through Christ. We must be “born-again” first before providing anything holy, Godly, joyously, or lovely…"}]},{"start":24,"end":25,"blocks":[{"kind":"para","text":"Here’s some encouragement. Trials are short. Life is short. Make it count with what you have. Eventually, you won’t have anything left to give, and so you want to give your all while you have it. God has granted you access through His Spirit to provide His fruits!"},{"kind":"scripture","text":"But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, Meekness, temperance: against such there is no law.","ref":"Galatians 5:22-23"},{"kind":"para","text":"The Spirit’s fruit is not given to us so we can partake of it. It’s given to us so we can give it to others to partake. When we have the Spirit’s fruit, it allows us the opportunity to bless those that we come into contact with. May that be a sobering thought to us to desire to live in the Spirit rather than the flesh. God’s Word is extremely important to the Spirit in which we provide to others. If we have not been refreshed in our Spirit, we must dive into God’s Word for refreshing. It is the only way we can receive it."}]}]}],"stories":[{"start":1,"end":1},{"start":2,"end":2},{"start":3,"end":3},{"start":4,"end":4},{"start":5,"end":5},{"start":6,"end":6},{"start":7,"end":7},{"start":8,"end":8},{"start":9,"end":11},{"start":12,"end":12},{"start":13,"end":13},{"start":14,"end":14},{"start":15,"end":15},{"start":16,"end":16},{"start":17,"end":17},{"start":18,"end":19},{"start":20,"end":20},{"start":21,"end":21},{"start":22,"end":23},{"start":24,"end":25}],"verses":{"1":"Peter, an apostle of Jesus Christ, to the strangers scattered throughout Pontus, Galatia, Cappadocia, Asia, and Bithynia,","2":"Elect according to the foreknowledge of God the Father, through sanctification of the Spirit, unto obedience and sprinkling of the blood of Jesus Christ: Grace unto you, and peace, be multiplied.","3":"Blessed be the God and Father of our Lord Jesus Christ, which according to his abundant mercy hath begotten us again unto a lively hope by the resurrection of Jesus Christ from the dead,","4":"To an inheritance incorruptible, and undefiled, and that fadeth not away, reserved in heaven for you,","5":"Who are kept by the power of God through faith unto salvation ready to be revealed in the last time.","6":"Wherein ye greatly rejoice, though now for a season, if need be, ye are in heaviness through manifold temptations:","7":"That the trial of your faith, being much more precious than of gold that perisheth, though it be tried with fire, might be found unto praise and honour and glory at the appearing of Jesus Christ:","8":"Whom having not seen, ye love; in whom, though now ye see him not, yet believing, ye rejoice with joy unspeakable and full of glory:","9":"Receiving the end of your faith, even the salvation of your souls.","10":"Of which salvation the prophets have enquired and searched diligently, who prophesied of the grace that should come unto you:","11":"Searching what, or what manner of time the Spirit of Christ which was in them did signify, when it testified beforehand the sufferings of Christ, and the glory that should follow.","12":"Unto whom it was revealed, that not unto themselves, but unto us they did minister the things, which are now reported unto you by them that have preached the gospel unto you with the Holy Ghost sent down from heaven; which things the angels desire to look into.","13":"Wherefore gird up the loins of your mind, be sober, and hope to the end for the grace that is to be brought unto you at the revelation of Jesus Christ;","14":"As obedient children, not fashioning yourselves according to the former lusts in your ignorance:","15":"But as he which hath called you is holy, so be ye holy in all manner of conversation;","16":"Because it is written, Be ye holy; for I am holy.","17":"And if ye call on the Father, who without respect of persons judgeth according to every man's work, pass the time of your sojourning here in fear:","18":"Forasmuch as ye know that ye were not redeemed with corruptible things, as silver and gold, from your vain conversation received by tradition from your fathers;","19":"But with the precious blood of Christ, as of a lamb without blemish and without spot:","20":"Who verily was foreordained before the foundation of the world, but was manifest in these last times for you,","21":"Who by him do believe in God, that raised him up from the dead, and gave him glory; that your faith and hope might be in God.","22":"Seeing ye have purified your souls in obeying the truth through the Spirit unto unfeigned love of the brethren, see that ye love one another with a pure heart fervently:","23":"Being born again, not of corruptible seed, but of incorruptible, by the word of God, which liveth and abideth for ever.","24":"For all flesh is as grass, and all the glory of man as the flower of grass. The grass withereth, and the flower thereof falleth away:","25":"But the word of the Lord endureth for ever. And this is the word which by the gospel is preached unto you."}},
    "2": {"chapter":2,"intro":[{"kind":"para","text":"Chapter: Chapter 02"},{"kind":"para","text":"Group: Tuesday"},{"kind":"para","text":"Status: Complete"},{"kind":"para","text":"Previously: Peter opens up his Epistle by reminding his readers the important thing to focus on when trials come. He even refers to the outcome of a trial and difficulty for a Christian as a time of joyfulness and pleasure. He has been using the term “precious” frequently, which is something we will continue to keep an eye out for, while we read through the rest of his epistles. He’s called our faith precious, and the blood of Christ precious so far. Ending the previous chapter, Peter reminds us how short life is, and why it’s important that we focus on the positives of Christ rather than the negatives of flesh, and he continues that theme into Chapter 2."}],"previously":["Peter opens up his epistle by reminding his readers the important thing to focus on when trials come. He even refers to the outcome of a trial and difficulty for a Christian as a time of joyful news and pleasure. He has been using the term “precious” frequently, which is something we will continue to keep an eye out for while we read through the rest of his epistles. He’s called our faith precious, and the blood of Christ precious so far. Ending the previous chapter, Peter reminds us how short life is, and why it’s important that we focus on the positives of Christ rather than the negatives of flesh, and he continues that theme into chapter 2."],"outline":[],"sections":[{"start":1,"end":8,"title":"Continuation From Previous Chapter","entries":[{"start":1,"end":2,"blocks":[{"kind":"para","text":"Defining words, I feel, is quite important, especially when we are reading from the King James. “Malice” simply means “ill-will” or “wickedness that is not shamed to break laws.” Sometimes associated with “Evil, trouble.” I have heard it likened to “congealed bitterness,” which I think suits the word the best. “Guile” simply means “deceit.”"},{"kind":"para","text":"Peter doesn’t say that we must pray that God would get rid of those things from our being, but rather that we would take action among our own spirit and influence to rid ourselves of things that are not pleasing to the Lord. If we are holding onto bitterness, deceit, envy, and evil speaking (not just evil, but even saying evil things), we cannot drink in God’s Word like we should. We have to lay those things aside! Once we take the effort to do specifically that, we are able then to turn to our Bibles and DESIRE God’s Word in the way God intends us. If we are not hungering for God’s Word, we cannot grow in God’s Spirit… We will never grow."},{"kind":"para","text":"A baby will not grow without its formula. A Christian will not grow without its spiritual feeding. Not just from the church, but from your own desires to spend time with God. This means to spend time with God’s WHOLE Word, not just grabbing a verse here and there to suffice us for later. If we are not looking into the “pure milk of the word” with the mindset of taking in as much as possible, we will never see God’s gifts grow in our lives, and we will continue to drown ourselves in malice, guile, hypocrisy, envy, and corrupt speech."}]},{"start":3,"end":3,"blocks":[{"kind":"para","text":"If you have tasted God’s grace, and you know what it means to receive a surplus of it, then you know it is possible to have that same grace bestowed upon you today. It would be a wise person’s dealing to try and figure out what is keeping them from receiving God’s overflowing grace, or refilling of the Spirit. Obviously, these people in which Peter is speaking too have experienced God’s grace, and have experienced God’s love and care, and some sort of trial and pain has kept the believers from doing the most basic of Christian things (which is to read their Word and search out God in all matters). That is why it’s canonical for us today. That’s why it exists in our Bibles."},{"kind":"para","text":"We are to have the full assurance of Scripture and canon to help us grow and fix our focus and walk on the right things."},{"kind":"scripture","text":"But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.","ref":"Matthew 6:33"},{"kind":"para","text":"Peter’s assertion is nothing new. It’s not a new doctrine or a new way of living. It’s a Christ-focused one, and it’s one that he personally learned from Jesus after facing some serious trials in his own ministry."}]},{"start":4,"end":4,"blocks":[{"kind":"para","text":"Circling back to Jesus’ affirmation when Peter refers to Him as the Christ, Jesus says, “upon THIS rock I will build my church…” He is the living stone. Christ may have been rejected by the world, but God never rejected His sacrifice. It’s through His sacrifice that we have the opportunity and privilege, not to just read His Word, but to KNOW Him THROUGH His Word. When we reject our desire to read and feed, we are essentially rejecting Christ."},{"kind":"scripture","text":"And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth.","ref":"John 1:14"}]},{"start":5,"end":5,"blocks":[{"kind":"para","text":"We are living stones, not because we are currently alive, but because Christ has made us alive. He has given us a living Spirit through His sacrifice on the cross. We are just as much alive as Christ is. If Christ is dead to you, you have no hope for your life. If He is non-existent to you, you have no hope for your life. If He is just an idea to you, you have no hope for your life. However, if He is alive to you, you are alive for all of eternity. Christ makes His children live because He lives."},{"kind":"para","text":"As far as I have known, studied, and prayed, Christ is still alive. Therefore, we are able to live with Him, have access to Him, and watch Him continuously work in our lives."}]},{"start":6,"end":6,"blocks":[{"kind":"para","text":"This was taken from Isaiah (which is a fantastic book linking to the life of Christ)."},{"kind":"scripture","text":"Therefore thus saith the Lord GOD, Behold, I lay in Zion for a foundation a stone, a tried stone, a precious corner stone, a sure foundation: he that believeth shall not make haste.","ref":"Isaiah 28:16"},{"kind":"para","text":"Obviously the chief corner stone is Christ. The real question is (and it’s one that will be answered soon enough) what is a cornerstone?"}]},{"start":7,"end":7,"blocks":[{"kind":"para","text":"There’s that word “precious” again. The cornerstone is precious to us because it means that everything will work out in comparison to that specific stone. If we follow the guidelines and rules of that stone, everything will be in its place, even if things start to get out of hand and burdensome. The cornerstone, obviously referring to Christ, will be the biggest factor in whether or not we will continue to stand strong. If we are not attached to Him, we are not going to stay together. Ultimately, this is what it will become…"}]},{"start":8,"end":8,"blocks":[{"kind":"para","text":"This is a quotation from Psalm."},{"kind":"scripture","text":"The stone which the builders refused is become the head stone of the corner.","ref":"Psalm 118:22"},{"kind":"para","text":"Someone linked this picture to the building of Solomon’s temple in 1 Kings."},{"kind":"scripture","text":"And the house, when it was in building, was built of stone made ready before it was brought thither: so that there was neither hammer nor axe nor any tool of iron heard in the house, while it was in building.","ref":"1 Kings 6:7"},{"kind":"para","text":"If you have never worked in construction, this verse is every contractor’s dream. Everything was cut and hewn before it reached the job site, so as soon as it arrived, it could just be put into place. There were no sounds of tools being used because everything was already perfectly fit together. I would have envied this when I worked in construction. A quiet worksite, everyone doing what they are supposed to, no need for measurements, no need for tools and cutting, no need for irritation because the measurements were wrong. Just smoothly placing everything where it’s supposed to go, one block at a time."},{"kind":"para","text":"The reason they were able to do this when Solomon was building the temple was not because they were really great at measuring and guessing how the building was going to perfectly fit together. They measured off of the cornerstone. It was only because the cornerstone was so perfect that the rest of the building could be perfectly formed together without tools."},{"kind":"para","text":"We are not so easily fit together. We require work, and it should not be like this. We should easily be able to fit together with Christ and other believers when we are born-again, so that we don’t have to struggle in our walks and bitterness. Those who stumble over the cornerstone should only be those who do not know Christ, not those who do. We, as Christians, are often stumbling over Christ, thinking we will be okay if we don’t spend time with Him in His Word, or in prayer, or in study and fellowship. We let those things which Peter tells us to put aside (in verse 2) become our main focus, and all that does is cause us to stumble."}]}]},{"start":9,"end":20,"title":"The Suffering of Saints, Compared","entries":[{"start":9,"end":9,"blocks":[{"kind":"para","text":"This is a fantastic verse! It’s one that deserves our full attention. It’s one that any preacher could preach an entire sermon on. Even an entire series on. We can’t miss what Peter is saying here, because it matters a lot in regards to our countenance and faithfulness to the Lord. It makes a difference between what we are doing, and what we SHOULD be doing. This is how Peter describes the believers."},{"kind":"para","text":"HE SAYS WE ARE CHOSEN!"},{"kind":"scripture","text":"Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you.","ref":"John 15:16"},{"kind":"para","text":"In the Old Testament, God chose the nation of Israel as His people. In the New Testament, God chose the church as His people. Even if we aren’t doing what we are supposed to be doing for the Lord, Peter reminds us that we are still chosen of God, and we have the opportunity to act that way."},{"kind":"para","text":"HE SAYS WE ARE A ROYAL PRIESTHOOD"},{"kind":"scripture","text":"And hath made us kings and priests unto God and his Father; to him be glory and dominion for ever and ever. Amen.","ref":"Revelation 1:6"},{"kind":"para","text":"Every Israelite was to be a priest in the Old Testament. In the New Testament, every child of God is to be a priest. The word “Catholic” means general. The Catholics have it wrong in their assumption that Catholicism is a religious practice generalized to their own personal faith and beliefs. We are ALL “Catholic Priests” when we are children of God. Christ is the head of the church, and if we are one with Christ, we are priests with Him as well."},{"kind":"para","text":"HE SAYS WE ARE A HOLY NATION!"},{"kind":"scripture","text":"Follow peace with all men, and holiness, without which no man shall see the Lord:","ref":"Hebrews 12:14"},{"kind":"para","text":"In the Old Testament, the holy nation that God chose was Israel. In the New Testament, the holy nation is the church! Of course, Israel had a lot of unholy lifestyles that were led multiple times through, and the church could be considered no different even still today. But they were meant to be holy by looking to God and standing affirmed in who HE is, and so is the church!"},{"kind":"para","text":"HE SAYS WE ARE A PECULIAR PEOPLE!"},{"kind":"para","text":"This means we are “God’s people” or a “people of His own.”"},{"kind":"scripture","text":"But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name:","ref":"John 1:12"},{"kind":"para","text":"We are confirmed in Him. He is the director of our faith. He is the director of our actions and desires. He gets to move us as He see’s fit. We are His."},{"kind":"scripture","text":"So we thy people and sheep of thy pasture will give thee thanks for ever: we will shew forth thy praise to all generations.","ref":"Psalm 79:13"}]},{"start":10,"end":10,"blocks":[{"kind":"para","text":"This should be a sobering thought to us that have fallen away or are struggling with our faith. God gives us mercy. We don’t deserve it. There was a time we didn’t receive it because we were completely against Him. But now that we know Him, God gives us mercy above what we should ever deserve."},{"kind":"scripture","text":"For he shall have judgment without mercy, that hath shewed no mercy; and mercy rejoiceth against judgment.","ref":"James 2:13"},{"kind":"para","text":"Mercy is the greatest focus that a child of God can view God in. If we see God’s mercy, we will be more inclined to love God more, because we will understand how undeserving we are to receive His mercy. Even more so, we are undeserving to even be in a relationship with God, yet that’s all He wants. We have no room to complain about what God does or desires to do in our lives, even if it is confusing and painful. We must look at God and wonder why He even desires to be with us at all…"}]},{"start":11,"end":11,"blocks":[{"kind":"para","text":"We don’t belong here. That’s a glorious revelation. This is not our home. We are looking forward to a home of our own. One to come in the future. We don’t know when, we don’t know what it will look like exactly. We have hopes and aspirations of how it will be, but we are still here. Until we get there, there’s no reason for us to stop hoping. But that should not deter us from doing what needs to be done until we get there."},{"kind":"para","text":"There are still things here on this Earth that need to be accomplished. There are things in this temporary home that need to be looked after. If we are so focused on the home to come, we will fall into the flesh in our present dwelling, because we will comfort ourselves in lusts and afflictions knowing that we will eventually get there anyway. We must pay attention to both. What we have now, and what we will eventually have in the future. This is so we can do as Peter recommends in the next verse…"}]},{"start":12,"end":12,"blocks":[{"kind":"para","text":"People don’t like people who are Christians or who go to church. They have a bad taste about them. It hurts, honestly. But that should not deter us from doing what we know is true and right. The ultimate goal (in this life) is not to just simply look out for yourself. The ultimate goal is to see others come to know Christ, and what is a better way to lead others to Him than to live a life that is honest in the eyes of God? If we are living lives that showcase God’s moving and dictation, we won’t even have to say a word about Him for others to start asking questions. Once again, Peter has experience in this area AS he was denying Christ."}]},{"start":13,"end":14,"blocks":[{"kind":"para","text":"This is a hard thought to swallow, but it seems that Peter is referring to the authority set over us. We are to obey those that have rule over us. The purpose of this is because God has put them in their place of rulership for a reason. There is a fine line that must be walked in order for us to KNOW the right line to cross and walk. COVID has caused a dividing line in a lot of areas (primarily in mask mandates and vaccines). The Christians were obedient for a time, but after a while of continuous pushback and beat down, there were Christians who opposed the authority and did what God desired them to do. Peter, of all people, understood the necessity to overthrow governments ruling at certain criteria."},{"kind":"scripture","text":"Then Peter and the other apostles answered and said, We ought to obey God rather than men.","ref":"Acts 5:29"},{"kind":"para","text":"Governmental authority should never overrule God’s authority, no matter what a pastor or preacher might try to teach you. Peter isn’t wrong in his logic in this area. He’s speaking to people that were under the rulership and laws of Nero (the psychopath). How do you obey a man who took joy and pleasure in burning down entire cities simply because there were Christians living there? Yet, here is Peter reminding them of their efforts for Christ. In Peter’s eyes, the obedience of the people during this persecution could mean the salvation of the leader who was persecuting them."}]},{"start":15,"end":15,"blocks":[{"kind":"para","text":"Once again, you wouldn’t even have to speak. All you would have to do is the right thing and it will get others talking."}]},{"start":16,"end":16,"blocks":[{"kind":"para","text":"The pulpit is loud, but your testimony towards others is louder. If we are not providing a graceful and Godly spirit when we are out in the world, it doesn’t matter what the pastor preaches behind his pulpit. It won’t have any effect if we are not able to take it and love others with it."}]},{"start":17,"end":17,"blocks":[{"kind":"para","text":"Respect others, love others, fear the Lord, and respect leadership. When we have the right mentality in these areas, it will be easy for us to walk rightly. In so doing, we will not have to worry about who we are reaching or how we are doing it because God’s Spirit will lead us into the right prospects."}]},{"start":18,"end":18,"blocks":[{"kind":"para","text":"To modernize this a little more, seeing as we don’t use this kind of language in the workplace now, what Peter is ultimately saying is “Employees, be subject to your bosses.” We are told how we are to work with those of both types, the “good and gentle” and the “froward (or perverse) and unreasonable” types. Be subject to them."},{"kind":"para","text":"The only time that you should not be is if they are asking you to do something that would be in direct disobedience to God. Maybe to lie, or to steal. Maybe to be unloving or harsh and hurtful. The term “be subject” means to do it out of choice, or voluntarily. Not because you have to, or because your boss is good so therefore you will be good, but because you know Christ and cannot but help do the right thing to everybody no matter who they may be or what they may have done (or have not done in some cases). Why? Why should we do this?…"}]},{"start":19,"end":20,"blocks":[{"kind":"para","text":"God sees your efforts. Employers and bosses may not, and they may not even care, but God takes a very special interest in those who do what is right to all, especially to those who are hateful and mean to their employees. God shows grace and favor to the employees who seek to please Him at all costs, no matter what, yet still receive no reward from their earthly bosses because of how distasteful and cruel they may be."},{"kind":"para","text":"In fact, God, when He sees this, is more inclined to put people in their places affirmatively. They usually experience a harder life outside of work because they are so against God and His commands for them in leadership. They don’t live prosperous lives, though they may think they do. They are sinful, guilty, and will never have a clean conscience before God. God will deal with them, and they will always feel like something is missing."},{"kind":"para","text":"Because we know and are certain that God will deal with the situation if we go to Him with it, we are able to rely on Him more when difficulties come. We are able to focus on Him more to do what needs to be done without the approval of others. We must look for the approval of God to know that you are doing the right thing."}]}]},{"start":21,"end":25,"title":"The Suffering of Christ","entries":[{"start":21,"end":22,"blocks":[{"kind":"para","text":"Christ suffering on the cross is the only example we cannot follow. His ministry examples are 100% something we should consider and look very deeply into. He even tells us…"},{"kind":"scripture","text":"For I have given you an example, that ye should do as I have done to you.","ref":"John 13:15"},{"kind":"para","text":"He suffered in multiple ways that didn’t just relate to His crucifixion. He suffered as a human being, just as much as we do. He was kind and loving even to people who were ultimately trying to kill Him and betray Him. He was loving to those that were in authority over Him, yet put God in His proper place above all earthly authority. He was constantly focused on what pleased the Father."},{"kind":"scripture","text":"And he that sent me is with me: the Father hath not left me alone; for I do always those things that please him.","ref":"John 8:29"},{"kind":"para","text":"This is an example that He left for us to follow! Peter gives examples of Christ’s etiquette as well…"}]},{"start":23,"end":23,"blocks":[{"kind":"para","text":"He simply did what He knew God would want Him to do, no matter the outcome (which the outcome for Christ was death, and He looked forward to because it meant the salvation of the world and the returning to His home). Christ looked forward to His future home, yet accomplished all the things that needed to be done in this temporary dwelling. And He did it with joy and willingness for US to accomplish the same…"}]},{"start":24,"end":24,"blocks":[{"kind":"para","text":"How are we living our lives in Christ’s sacrifices? Are we taking our new lives for granted? Why? What is in our way of being fervent in our relationship and walk with Christ? What in this world could keep us from doing what is right? What kind of life should we be living?"}]},{"start":25,"end":25,"blocks":[{"kind":"para","text":"Peter quotes from the Old Testament again."},{"kind":"scripture","text":"All we like sheep have gone astray; we have turned every one to his own way; and the LORD hath laid on him the iniquity of us all.","ref":"Isaiah 53:6"},{"kind":"para","text":"Christ suffered to set for us an example. He showed us how we are to deal with situations of suffering and trial especially when it comes from people in leadership above you."},{"kind":"scripture","text":"They say unto him, Caesar's. Then saith he unto them, Render therefore unto Caesar the things which are Caesar's; and unto God the things that are God's.","ref":"Matthew 22:21"},{"kind":"para","text":"This should be a wake up call as to whom we serve and what priorities we should be placing in the Lord."}]}]}],"stories":[{"start":1,"end":2},{"start":3,"end":3},{"start":4,"end":4},{"start":5,"end":5},{"start":6,"end":6},{"start":7,"end":7},{"start":8,"end":8},{"start":9,"end":9},{"start":10,"end":10},{"start":11,"end":11},{"start":12,"end":12},{"start":13,"end":14},{"start":15,"end":15},{"start":16,"end":16},{"start":17,"end":17},{"start":18,"end":18},{"start":19,"end":20},{"start":21,"end":22},{"start":23,"end":23},{"start":24,"end":24},{"start":25,"end":25}],"verses":{"1":"Wherefore laying aside all malice, and all guile, and hypocrisies, and envies, and all evil speakings,","2":"As newborn babes, desire the sincere milk of the word, that ye may grow thereby:","3":"If so be ye have tasted that the Lord is gracious.","4":"To whom coming, as unto a living stone, disallowed indeed of men, but chosen of God, and precious,","5":"Ye also, as lively stones, are built up a spiritual house, an holy priesthood, to offer up spiritual sacrifices, acceptable to God by Jesus Christ.","6":"Wherefore also it is contained in the scripture, Behold, I lay in Sion a chief corner stone, elect, precious: and he that believeth on him shall not be confounded.","7":"Unto you therefore which believe he is precious: but unto them which be disobedient, the stone which the builders disallowed, the same is made the head of the corner,","8":"And a stone of stumbling, and a rock of offence, even to them which stumble at the word, being disobedient: whereunto also they were appointed.","9":"But ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people; that ye should shew forth the praises of him who hath called you out of darkness into his marvellous light:","10":"Which in time past were not a people, but are now the people of God: which had not obtained mercy, but now have obtained mercy.","11":"Dearly beloved, I beseech you as strangers and pilgrims, abstain from fleshly lusts, which war against the soul;","12":"Having your conversation honest among the Gentiles: that, whereas they speak against you as evildoers, they may by your good works, which they shall behold, glorify God in the day of visitation.","13":"Submit yourselves to every ordinance of man for the Lord's sake: whether it be to the king, as supreme;","14":"Or unto governors, as unto them that are sent by him for the punishment of evildoers, and for the praise of them that do well.","15":"For so is the will of God, that with well doing ye may put to silence the ignorance of foolish men:","16":"As free, and not using your liberty for a cloke of maliciousness, but as the servants of God.","17":"Honour all men. Love the brotherhood. Fear God. Honour the king.","18":"Servants, be subject to your masters with all fear; not only to the good and gentle, but also to the froward.","19":"For this is thankworthy, if a man for conscience toward God endure grief, suffering wrongfully.","20":"For what glory is it, if, when ye be buffeted for your faults, ye shall take it patiently? but if, when ye do well, and suffer for it, ye take it patiently, this is acceptable with God.","21":"For even hereunto were ye called: because Christ also suffered for us, leaving us an example, that ye should follow his steps:","22":"Who did no sin, neither was guile found in his mouth:","23":"Who, when he was reviled, reviled not again; when he suffered, he threatened not; but committed himself to him that judgeth righteously:","24":"Who his own self bare our sins in his own body on the tree, that we, being dead to sins, should live unto righteousness: by whose stripes ye were healed.","25":"For ye were as sheep going astray; but are now returned unto the Shepherd and Bishop of your souls."}},
    "3": {"chapter":3,"intro":[{"kind":"para","text":"Chapter: Chapter 03"},{"kind":"para","text":"Group: Tuesday"},{"kind":"para","text":"Status: Complete"},{"kind":"para","text":"## Previously: In the last chapter, Peter spoke about how we can suffer well. A vain in which Peter continues throughout this entire book, and the next, for Peter is learning these lessons as well before his own crucifixion. He talked about how we can all suffer together as brothers in the faith, how our suffering compares to the suffering of the rest of the world (another vain that is continued), and how to comply with evil leaders in our day. He ended the chapter with the suffering of Christ, and what that meant for us as believers."},{"kind":"para","text":"In this chapter, we see Peter seemingly change course, but in context, Peter is using important personal examples to help demonstrate his previous comments on suffering, and living peaceable lives with others."}],"previously":["In the last chapter, Peter spoke about how we can suffer well (a vein in which Peter continues throughout this entire book, and the next, for Peter is learning these lessons as well before his own crucifixion). He talked about how we can all suffer together as brothers in the faith, how our suffering compares to the suffering of the rest of the world (another vein that is continued), and how to comply with evil leaders in our day. He ended the chapter with the suffering of Christ, and what that meant for us as believers. In this chapter, we see Peter seemingly change course, but in context, Peter is using important personal examples to help demonstrate his previous comments on suffering, and living peaceable lives with others."],"outline":[],"sections":[{"start":1,"end":7,"title":"Wives and Husbands","entries":[{"start":1,"end":1,"blocks":[{"kind":"para","text":"Speaking primarily to the wives, those married to unbelievers have a responsibility to continuously act Christlike. They won’t even have to speak and will still be able to win their husbands over. This could also be applied to the married women of Christian men. Sometimes Christian men aren’t doing what they are supposed to, and it shows through their actions. The wives are not supposed to overthrow their authority but continue to act in a Christ-like manner so that the husband can be won over by the appropriate conversations of the wife."},{"kind":"para","text":"Of course, the term “likewise” is Peter’s way of tying in the previous chapter’s comments on obeying bosses in the same way that you would obey and love your spouse. Leading under the same guise, if the husband is doing something sinful and wrong, the wife is not supposed to follow in that. However, she is to give him reverence and sympathy for those things that are appropriate and acceptable (like would be the case if you had to decide the proper outcome for a boss as an employee)."},{"kind":"para","text":"I read about a situation where a wife was struggling with her husband’s addiction to the strip club. When she went to the pastor, supposedly the pastor read from this verse and said that she is required to go with him anyway to the club whether she likes it or not. It was commanded to her to go to the club and continue to be an example. Obviously, this is very wrong, and the scripture is twisted here. She is not to condone such actions from her husband and is not to go with him to those places. The pastor who recommended obeying her husband in this instance is guilty of condoning sin in this couple’s lives and will be the person responsible for destroying a marriage. It’s good to get a second biblical opinion if something doesn’t sound right from your pastor or leader."}]},{"start":2,"end":2,"blocks":[{"kind":"para","text":"Of course, the husbands that don’t know Christ can be won over because of the wife’s commitment to the Lord. If the husband feels you are more committed to God than you are to him, they will usually fight for that position. As we may know, they will never win it, but they can achieve equal love towards God if the husband is willing to submit to His authority, allowing the proper respect to the wife, so making it easier for the wife to submit to the husband’s authority."}]},{"start":3,"end":3,"blocks":[{"kind":"para","text":"It is not by the way you look, or how hard you try to make yourself presentable that will win him over. It has to be done through your acts and deeds that will make a man look to the Lord."}]},{"start":4,"end":4,"blocks":[{"kind":"para","text":"The ornament of a gentle and quite spirit speaks louder than forcible conversion."}]},{"start":5,"end":5,"blocks":[{"kind":"para","text":"This links back to the samples left for us in the Old Testament. It wasn’t solely based upon their looks that their husbands turned to the Lord. Most of the best examples in the Old Testament prove that the husband was already living for the Lord before they were married, and the wives that they chose were either won over by the husband’s faith or were already faithful to the God that their husbands were serving. The same is still relevant today."},{"kind":"para","text":"Women are much easier to win over if their husbands are won over first. There’s an obvious biblical connection to this, which could evidently be traced back to the first sin in the garden. If the wife is saved before the husband, it’s usually much harder for the husband to come to terms with salvation."}]},{"start":6,"end":6,"blocks":[{"kind":"para","text":"In case you don’t remember, Abraham had to tell several rulers that his wife was his sister because apparently she was a very beautiful woman. But she was only obedient to Abraham, even though kings of all kinds wanted her as a wife. Obviously, Sara looked up to Abraham as the leader that he was meant to be (even though he messed up more times than we can count)."}]},{"start":7,"end":7,"blocks":[{"kind":"para","text":"Peter has now turned course to speak to the husbands of the faith. He instructs the men to be sensitive to the needs of the wife and giving them honor because they are a “weaker vessel.” Women are to be held in high reverence, and men are to support the woman in uplifting and helping her because she’s not as strong as a man in physical stature. That’s just basic biology."},{"kind":"para","text":"Women should love to be women, and they should love to be treated like such, as much as a man should love to be treated like a man. How is it possible that women would want to be treated like men, and men like women in today’s age? I think it’s because of the many households (primarily in America) where the husband has dishonored the wife, caused her to rely on herself, and the wife has forsaken the chance to converse and win over her husband. Now we have people confused about how a woman and a man are supposed to be treated."},{"kind":"para","text":"I also like the fact that Peter mentions that husbands and wives are “heirs together of the grace of life” and if we are not treating our spouses right in the way that God intends us to, Peter warns us that our prayers (no matter the size and strength of them) will be hindered or unanswered. I’m willing to bet that a great many religionists, with their repeated prayers and vain conversations in the Lord, would have their prayers heard (though it be in vain) if their relationships in their marriages were in the right standing. Of course, they can’t have the right relationship with each other if they don’t first have the right relationship with Christ, but it would certainly be an eye-opening experience if they took these simple labels here in 1 Peter and applied them directly in their lives today. How could the wife speak to the husband about Christ if she does not love Christ first? How can a husband lead his family for Christ if he does not know Christ first?"}]}]},{"start":8,"end":22,"title":"Suffering For Righteousness' Sake","entries":[{"start":8,"end":8,"blocks":[{"kind":"para","text":"Going back to the church, we are to treat everyone in this same regard. Take special care of our spouses, but still take care of the others in the church. We should love God, love our spouse, love our kids, and then love the church. If this list is out of order in any way, we will not be successful in our relationships. Loving the church properly REQUIRES us to love our spouses properly first. Even Paul speaks about this."},{"kind":"scripture","text":"One that ruleth well his own house, having his children in subjection with all gravity; (For if a man know not how to rule his own house, how shall he take care of the church of God?)","ref":"1 Timothy 3:4-5"}]},{"start":9,"end":9,"blocks":[{"kind":"para","text":"This is certainly a wake-up call for the church. People will treat others in evil ways whether we like it or not. It’s just what people do; that’s how they will act no matter what. However, the church is supposed to bless those that are evil towards us. We need to get this in our heads because it’s missing in our culture today. We need to give love to our enemies."},{"kind":"scripture","text":"But I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you;","ref":"Matthew 5:44"},{"kind":"para","text":"If we are able to take Jesus’ words to heart on the matter, we will see much greater victories in everything we do, including the work that God has called us too."}]},{"start":10,"end":10,"blocks":[{"kind":"para","text":"Peter really pinpoints the issue today. Believers (of course) want to live. We have no doubt in ourselves that our lives are valuable and are purposeful because of what Jesus has done for us. However, many believers today don’t love life. If you really want to enjoy life, Peter tells us exactly how to do that in this verse. He tells us to keep from saying evil and hateful things, and to stop ourselves from lying and being deceptive. That’s how we can get true joy out of this life."}]},{"start":11,"end":11,"blocks":[{"kind":"para","text":"Living our best life (like Joel Osteen would try to accommodate by other means) is through eschewing (or rejecting) evil and doing what’s right; those that are looking to keep peace and are pursuing peace are the ones that will have their best lives lived out. If we cannot live our lives in this way, we will not love life like we should. The value that Jesus puts on our lives by dying for us gives us more value than we are acting."}]},{"start":12,"end":12,"blocks":[{"kind":"para","text":"This is actually a quote from Psalm."},{"kind":"scripture","text":"The eyes of the LORD are upon the righteous, and his ears are open unto their cry. The face of the LORD is against them that do evil, to cut off the remembrance of them from the earth.","ref":"Psalm 34:15-16"},{"kind":"para","text":"Peter further illustrates another happenstance of hindered prayer. God will not hear the prayers of those who are not His own. He promises to hear those that are His, but those who aren’t His will have hindered prayers."}]},{"start":13,"end":13,"blocks":[{"kind":"para","text":"Great question. But this does not mean that we will not be harmed, or that there won’t be attacks on us just because we know the Lord and we are living for Him. In fact, I’d argue to say that there will be more attacks BECAUSE you’re a child of God rather than if you weren’t."}]},{"start":14,"end":14,"blocks":[{"kind":"para","text":"Happy for suffering? Why? Because (as Peter has already illustrated) it makes our faith and love for the Lord stronger. We’ve been through a great deal of turmoil and trials, we know how difficult suffering is, and how unwanted it seems. But, having been through it, and still coming out the other side of it, I am happy that we experienced what we did. We are in a better position (spiritually) now than we were before. If we are not, it certainly can be because we are still able to learn some really important and valuable lessons through the issues that have been presented to us."}]},{"start":15,"end":15,"blocks":[{"kind":"para","text":"Being prepared to tell everyone about the faith that you have is the ultimate purpose of our existence. We should not do anything in this life without preparation, and (even more so) we should not move throughout our day without the sensitivity to use what God has prepared you for. With God’s calling always comes God’s enabling. However, we have the opportunity to completely botch the enablement of God because we refuse to use those things that He has prepared us to use."}]},{"start":16,"end":16,"blocks":[{"kind":"para","text":"We should not be surprised if evil people do evil things. That’s like being shocked because a vacuum sucks. Or being amazed that a knife can cut. Of course, those things can do that; that’s what they were designed to do. Now, evil people were designed to do evil things, and our desire (of course) is that they would turn from their evil and take hold of the goodness of God. This will ultimately take time, but until then, we are to do the right thing to evil people; they will feel guilty later for what they have done because God will reveal it. If they don’t feel guilty, they are still evil, and God has not redeemed them yet."}]},{"start":17,"end":17,"blocks":[{"kind":"para","text":"Think about this. No matter what we do, we will suffer. Will we suffer because we did what was right? Or will we suffer because we did what was wrong? Which would be the better reason to suffer? At least if we suffer for doing right, the suffering will be passed on. But those that suffer for doing what is wrong will have to hold onto their suffering."}]},{"start":18,"end":18,"blocks":[{"kind":"para","text":"If you link your suffering back to Christ, you will realize that Christ suffered for much of the same things, if not worse! He suffered death for being God. He didn’t do anything else but what God’s Word told Him to. He did it better than the religionists of His day (and even still today) and He suffered for it. He, however, is the example we should follow, and we should expect to be treated the same way if that was how He was treated for doing the same things."},{"kind":"para","text":"If we are expecting applause and apologies from others because of our work that Christ was crucified for, then we should not do the work in which Christ bids us. In fact, it’s a good indication that we probably don’t know Christ all too well…"}]},{"start":19,"end":19,"blocks":[{"kind":"para","text":"This is a very confused verse of Scripture. A lot of people assume that Peter is mentioning Christ preaching the gospel to angels in Hell. But verse 20 gives us a timeframe that Peter is speaking on…"}]},{"start":20,"end":20,"blocks":[{"kind":"para","text":"When did Christ preach to the spirits in prison? “When once the longsuffering of God waited in the days of Noah.” They rejected the message of Noah, and now their spirits are in prison because of it. Christ, of course, did not go down and preach to them. That was not His reward for dying on the cross (that sounds like a terrible reward, seeing as He was excited and proclaimed that He was going to see His father after His crucifixion)."},{"kind":"scripture","text":"Then said Jesus again unto them, I go my way, and ye shall seek me, and shall die in your sins: whither I go, ye cannot come. Then said the Jews, Will he kill himself? because he saith, Whither I go, ye cannot come. And he said unto them, Ye are from beneath; I am from above: ye are of this world; I am not of this world. I said therefore unto you, that ye shall die in your sins: for if ye believe not that I am he, ye shall die in your sins.","ref":"John 8:21-24"},{"kind":"scripture","text":"And Jesus said unto him, Verily I say unto thee, Today shalt thou be with me in paradise.","ref":"Luke 23:43"},{"kind":"para","text":"He preached through Noah. For one hundred and twenty years, Noah preached God’s Word. He saved his family, but no one else. The premise is that the Word of God means nothing to those today who reject Christ, just as it meant nothing to those that heard Noah’s message and rejected it back then."}]},{"start":21,"end":21,"blocks":[{"kind":"para","text":"The Holy Spirit’s baptism is real baptism. It isn’t speaking about water baptism. Though even if it were, Peter further illustrates that the baptism which is being referred to here is not the putting away of the flesh (or cleansing you of sin) but the answer of a good conscience toward God (or a renewed Spirit in God showing your salvation)."}]},{"start":22,"end":22,"blocks":[{"kind":"para","text":"Christ has all things under His power. He has power, but we have access to it because of what He did for us on the cross. When we are going through difficulty, and we are being mistreated for something that we shouldn’t be mistreated for, we can come to Christ with full assurance, and be lifted by His power and grace. This is what will ultimately bring our care and value back into perspective."}]}]}],"stories":[{"start":1,"end":1},{"start":2,"end":2},{"start":3,"end":3},{"start":4,"end":4},{"start":5,"end":5},{"start":6,"end":6},{"start":7,"end":7},{"start":8,"end":8},{"start":9,"end":9},{"start":10,"end":10},{"start":11,"end":11},{"start":12,"end":12},{"start":13,"end":13},{"start":14,"end":14},{"start":15,"end":15},{"start":16,"end":16},{"start":17,"end":17},{"start":18,"end":18},{"start":19,"end":19},{"start":20,"end":20},{"start":21,"end":21},{"start":22,"end":22}],"verses":{"1":"Likewise, ye wives, be in subjection to your own husbands; that, if any obey not the word, they also may without the word be won by the conversation of the wives;","2":"While they behold your chaste conversation coupled with fear.","3":"Whose adorning let it not be that outward adorning of plaiting the hair, and of wearing of gold, or of putting on of apparel;","4":"But let it be the hidden man of the heart, in that which is not corruptible, even the ornament of a meek and quiet spirit, which is in the sight of God of great price.","5":"For after this manner in the old time the holy women also, who trusted in God, adorned themselves, being in subjection unto their own husbands:","6":"Even as Sara obeyed Abraham, calling him lord: whose daughters ye are, as long as ye do well, and are not afraid with any amazement.","7":"Likewise, ye husbands, dwell with them according to knowledge, giving honour unto the wife, as unto the weaker vessel, and as being heirs together of the grace of life; that your prayers be not hindered.","8":"Finally, be ye all of one mind, having compassion one of another, love as brethren, be pitiful, be courteous:","9":"Not rendering evil for evil, or railing for railing: but contrariwise blessing; knowing that ye are thereunto called, that ye should inherit a blessing.","10":"For he that will love life, and see good days, let him refrain his tongue from evil, and his lips that they speak no guile:","11":"Let him eschew evil, and do good; let him seek peace, and ensue it.","12":"For the eyes of the Lord are over the righteous, and his ears are open unto their prayers: but the face of the Lord is against them that do evil.","13":"And who is he that will harm you, if ye be followers of that which is good?","14":"But and if ye suffer for righteousness' sake, happy are ye: and be not afraid of their terror, neither be troubled;","15":"But sanctify the Lord God in your hearts: and be ready always to give an answer to every man that asketh you a reason of the hope that is in you with meekness and fear:","16":"Having a good conscience; that, whereas they speak evil of you, as of evildoers, they may be ashamed that falsely accuse your good conversation in Christ.","17":"For it is better, if the will of God be so, that ye suffer for well doing, than for evil doing.","18":"For Christ also hath once suffered for sins, the just for the unjust, that he might bring us to God, being put to death in the flesh, but quickened by the Spirit:","19":"By which also he went and preached unto the spirits in prison;","20":"Which sometime were disobedient, when once the longsuffering of God waited in the days of Noah, while the ark was a preparing, wherein few, that is, eight souls were saved by water.","21":"The like figure whereunto even baptism doth also now save us (not the putting away of the filth of the flesh, but the answer of a good conscience toward God,) by the resurrection of Jesus Christ:","22":"Who is gone into heaven, and is on the right hand of God; angels and authorities and powers being made subject unto him."}},
    "4": {"chapter":4,"intro":[{"kind":"para","text":"Chapter: Chapter 04"},{"kind":"para","text":"Group: Tuesday"},{"kind":"para","text":"Status: Complete"},{"kind":"para","text":"## Previously: Our last chapter focused on the importance of a Godly marriage and how to treat our spouses with the amount of respect they deserve. Ultimately, Peter stuck to the most important task at hand, and that was how to suffer well in our Christian walk. Having a spouse makes it just a little easier to suffer together, seeing as we are heirs together in the same grace and walk with God. When you suffer, your spouse suffers with you. Peter pointed out the right kind of suffering, because no matter what, as Christians, we will always experience suffering. We just have a choice on what to suffer for, whether for doing right, or doing wrong."},{"kind":"para","text":"In this chapter, Peter is giving us a warning about when things are easy. We must continue to stay vigilant and thoughtful, especially when things are going well. When things are tough, we have no choice but to think through the trial and find a solution. When things are easy, we tend to let our guards down. This is not an easy saying, and it’s certainly not one that you are going to like to hear, but it’s true nevertheless... Suffering gives us guidance."}],"previously":["Our last chapter focused on the importance of a Godly marriage and how to treat our spouses with the amount of respect they deserve. Ultimately, Peter stuck to the most important task at hand, and that was how to suffer well in our Christian walk. Having a spouse makes it just a little easier to suffer together, seeing as we are heirs together in the same grace and walk with God. When you suffer, your spouse suffers with you. Peter pointed out the right kind of suffering, because no matter what (as Christians) we will always experience suffering. We just have a choice on what to suffer for, whether for doing right or doing wrong. In this chapter, Peter is giving us a warning about when things are easy. We must continue to stay vigilant and thoughtful, especially when things are going well. When things are easy, we tend to let our guards down. This is not an easy saying, and it’s certainly not one that you are going to like to hear, but it’s true nevertheless… Suffering gives us guidance."],"outline":[],"sections":[{"start":1,"end":11,"title":"Stewards of God's Grace","entries":[{"start":1,"end":1,"blocks":[{"kind":"para","text":"This verse of scripture brings us back to our last chapter of 1 Peter."},{"kind":"scripture","text":"For Christ also hath once suffered for sins, the just for the unjust, that he might bring us to God, being put to death in the flesh, but quickened by the Spirit:","ref":"1 Peter 3:18"},{"kind":"para","text":"The term here for “ceased” means… “ceased, or to stop…” It’s also used by Paul."},{"kind":"scripture","text":"Charity never faileth: but whether there be prophecies, they shall fail; whether there be tongues, they shall cease; whether there be knowledge, it shall vanish away.","ref":"1 Corinthians 13:8"},{"kind":"para","text":"This means that speaking in tongues will stop. But Peter is not saying that we will stop sinning, though suffering certainly gives us reality and approval/purpose to stop sinning. What he is really saying is suffering will release us from sin. Christ is your identity, not your sin. 2 That he no longer should live the rest of his time in the flesh to the lusts of men, but to the will of God."},{"kind":"para","text":"We are not defined by our sin. However, we should still have standards of living in Christ. We know how He lives. We should have the same “mind” or same “thought (for a better definition)” as He did in regards to suffering and living in holiness. He knows how it is to suffer for holiness’ sake."},{"kind":"para","text":"3 For the time past of our life may suffice us to have wrought the will of the Gentiles, when we walked in lasciviousness, lusts, excess of wine, revellings, banquetings, and abominable idolatries:"},{"kind":"para","text":"How can we continue to live in our past sins and lifestyle knowing what we’ve been rescued from? How can we continue to say we love Christ but live a life that is completely opposite of showing that actual love? How can we even be around those that are of a different mindset on their lifestyle, and would try to entice you into their ungodliness? It wouldn’t make sense to be a Christian, and still live our lives with no change. 4 Wherein they think it strange that ye run not with them to the same excess of riot, speaking evil of you:"},{"kind":"para","text":"They will ask, “Why don’t you do what you used to?” They will say, “I miss the way our friendship used to be before you became a Christian.” They will be confused, hurt, and discouraged by your conduct of living because it has a standard now. They would rather you be in the mire with them. They want you to live in the pigpen, wallowing in their suffering with them. The world’s suffering proves foolishness. Christian suffering proves direction."},{"kind":"para","text":"5 Who shall give account to him that is ready to judge the quick and the dead."},{"kind":"para","text":"The term “quick” simply means “living.” God will judge both the saved and the unsaved based on their current way of living. Whether you live to the world without Christ and in your sins, or you live in the Lord with Christ and in righteousness, that is how your judgement will be viewed. 6 For for this cause was the gospel preached also to them that are dead, that they might be judged according to men in the flesh, but live according to God in the spirit."},{"kind":"para","text":"The knowledge of God’s judgment will give us two life views. We will either be judged for our lifestyle, or we will live in God’s Spirit. Those are the two certainties that every human being will choose when they come to know the knowledge of God’s judgment. 7 But the end of all things is at hand: be ye therefore sober, and watch unto prayer."},{"kind":"para","text":"I’ve already noted this before, but the end of all things started when Christ returned to Heaven. We had a knowledge at that point that in Christ’s first coming, it was for eternal life, but in Christ’s second coming it will be for an eternal death. We are currently living in the end times because Christ has already made His first coming. 8 And above all things have fervent charity among yourselves: for charity shall cover the multitude of sins."},{"kind":"para","text":"This is incredible wisdom by Peter here. He has learned from two of the wisest men to have ever lived. He personally learned from Jesus as He was here on Earth. He learned from Adam (who we could argue to have been one of the wisest men to have ever lived), and he has obviously learned from Solomon."},{"kind":"scripture","text":"Hatred stirreth up strifes: but love covereth all sins.","ref":"Proverbs 10:12"},{"kind":"para","text":"Whether he was intentionally quoting Solomon here or not is not for me to say. I do know, however, that love speaks louder than hate. We tend to remember hate more, but it will not suffice for our deepest spiritual need, which can only be found in love. A church that provides hatred more than love will cause divisions and issues between the believers. It is not the church’s duty to carelessly and callously point out human flaws. God’s Word will do that for us if we are using it in love. It is, however, the church’s job to provide love and care for the brothers and the poor in spirit."},{"kind":"scripture","text":"Blessed are the poor in spirit: for theirs is the kingdom of heaven.","ref":"Matthew 5:3"},{"kind":"para","text":"This is especially important to a hurting people, and a suffering body. Read this next verse… 9 Use hospitality one to another without grudging."},{"kind":"para","text":"This is a great church identifier! You can tell a lot about a church and Christians by their proof of hospitality. A church that is hospitable is a church that provenly loves the Lord. This should be the standard in which we measure our church homes. Are they loving one another with hospitality, or are they butting heads and carrying grudges with everyone they are around? 10 As every man hath received the gift, even so minister the same one to another, as good stewards of the manifold grace of God."},{"kind":"para","text":"This is an important verse for this chapter and for our walks in Christ. We are given gifts from the Lord in ministry and life. We are gifted with family, friends, and ministries that He has entrusted us with. Even more so, He has gifted us with emotions, thoughts, knowledge, love, and even suffering. Everything we have in this life (no matter how small or big it may be) is a gift from the Lord. Peter reminds us of our most needful purpose as Christians: stewardship. Stewardship."},{"kind":"para","text":"Stewardship is not just keeping track of the things you have; it’s actually about using what you’ve been given properly. Even more so, it’s about taking care of someone else’s possessions. Peter warns the readers to look at their current happenstance and possessions and ask themselves, “What would God like me to do with this?” I’m still learning in this area myself, but I’ve come to refocus my thinking and live in peace knowing that everything is Gods. I’ve let go of it all and just trust the Lord with it."},{"kind":"para","text":"Sometimes it seems hard and unwanted, but I implore you not to take back control because of how burdensome it can be in some areas of our lives. Give God control of it all and ask Him where to go next. All of it. Not some of it; all of it. Try it for one whole day and see what God can do. Most of all, steward the grace in which God has bestowed upon you. Use it for Gods glory so others can feel Gods gift of grace. Peter demonstrates how to do this: 11 If any man speak, let him speak as the oracles of God; if any man minister, let him do it as of the ability which God giveth: that God in all things may be glorified through Jesus Christ, to whom be praise and dominion for ever and ever. Amen."},{"kind":"para","text":"It’s by God’s sufficiency and reliance that we are able to have any kind of good conduct or affirmative care from Him. Our examples are not brought on by our own personalities. Our examples of anything we do should only be provided because the Lord has led the way through it all. That should be our ultimate goal: Show what the Lord has done, because it wouldn’t be possible for it to be done if we were in control."}]}]},{"start":12,"end":19,"title":"Suffering as a Christian","entries":[{"start":12,"end":12,"blocks":[{"kind":"para","text":"We’ve had a few verses so far through this letter from Peter speaking about “fiery trials.” He’s given us a lot of application in regards to how to deal with trials, and how hot and terrible they are going to feel, yet we are supposed to endure them with joy and patience. Now he tells us that we shouldn’t think it’s strange that we are being tried. In other words, “Loved ones, the things that you are going through should not shock you by any means. This shouldn’t be a surprise to you that you are going through difficulties. Christ went through these self-same ones for the self-same reasons. Why would it be strange if it is happening to you?” That’s like a smoker being surprised that he has developed cancer. “How could cancer come to someone like me? I exercise, I eat healthy, I am never around anyone that could bring me down, I have joy in my life, a nice car, lots of money, a loving family, and a great job! Why would I have cancer?” He asks as he smokes his last cigarette."},{"kind":"para","text":"If we are Christians, we should not be surprised that we are hated by the world. We should not be surprised if we are tried for our faith and way of living. We should not be surprised if our code of conduct turns people away or offends people because you have chosen to love Christ over everything. If it surprises you every time a trial comes, you should better get used to it if you want to live a life for Christ. Otherwise, it will never stop surprising you, and you will never stop going through trials. 13 But rejoice, inasmuch as ye are partakers of Christ's sufferings; that, when his glory shall be revealed, ye may be glad also with exceeding joy."},{"kind":"para","text":"The reason we should have joy in suffering through trials is because suffering prepares us for Christ’s coming."},{"kind":"scripture","text":"And if children, then heirs; heirs of God, and joint-heirs with Christ; if so be that we suffer with him, that we may be also glorified together.","ref":"Romans 8:17"},{"kind":"para","text":"We cannot get around the trials that we are going to face. Christ WANTS us to go through the trials, but He wants us to go through them WITH Him. That should be our ultimate comfort. 14 If ye be reproached for the name of Christ, happy are ye; for the spirit of glory and of God resteth upon you: on their part he is evil spoken of, but on your part he is glorified."},{"kind":"para","text":"If you are afflicted, you are mocked, you are scorned, you are bruised, you are beaten, you are reviled, you are hated, and loathed, for Christ’s sake, you are not alone. You cannot just be joyous in this, but Peter declares that we can be “happy.” Happy to be afflicted. Happy to be mocked. Happy to be scorned. Happy to be bruised. Happy to be beaten. Happy to be reviled. Happy to be hated. Happy to be loathed. If it’s for Christ, then it’s worth all the pain this world can give us. 15 But let none of you suffer as a murderer, or as a thief, or as an evildoer, or as a busybody in other men's matters."},{"kind":"para","text":"Imagine that… It was easy for Moses to use his own power and strength to confront someone because of their evil doings. While Moses was trying to defend someone else from mistreatment, he was still guilty of murdering another person. It’s a heinous crime, and he would suffer consequences for that action. However, God still uses him, changes him, and provides salvation for his people."},{"kind":"para","text":"Even more so, we are warned that even hating your brother is murder. That doesn’t bring justice to your soul and spirit. All hate does is bring more suffering. It would be far better to love someone and suffer for it than to hate someone and suffer. 16 Yet if any man suffer as a Christian, let him not be ashamed; but let him glorify God on this behalf."},{"kind":"para","text":"Let us say, “Thank you Lord for allowing this trial.” 17 For the time is come that judgment must begin at the house of God: and if it first begin at us, what shall the end be of them that obey not the gospel of God?"},{"kind":"para","text":"Judgement begins with us, and our judgement must be righteous. Not only so, but when God judges us (which is the standard of righteous judgement), it should be eye-opening to us about the judgments that our lost neighbors will endure. We all deserve Hell, but only those that don’t obey the gospel will receive it. 18 And if the righteous scarcely be saved, where shall the ungodly and the sinner appear?"},{"kind":"para","text":"This is funny to me. Peter says we are saved by the skin of our teeth. We will just barely make it into Heaven. Not because of who we are, or what we do, but because Jesus brings us there. We will barely make it, and those that don’t have Jesus will never even have a chance. It’s like someone that builds a bridge."},{"kind":"para","text":"Rope bridges have always fascinated me, especially when they go over a long gap. How do they get the rope to the other side? I imagine that they have some sort of length of rope that they assume would make it across. Some would venture with a measurement of rope, and if the rope wasn’t long enough, there’s no way they would be able to toss or shoot that rope across the gap. They need the right measurements (they also need the measurements of the gap), the right strength to throw the rope (or some way to shoot it across the gap), the right angle to keep the bridge from collapsing or stretching too much after it has been planted and secured, and the right kind of tools to plant the posts to hold the bridge on each side of the gap. There’s a lot of thought and preparation that goes into it. If any of that is off, they will not make it. If they guess, they will just barely make it (if they are lucky), and if they barely make it, there won’t be enough slack or stretch in the rope for it to flex when people walk across, which would cause posts to come loose, or ropes to snap, or boards to break…"},{"kind":"para","text":"With Christ, we are not guessing the gap. The math and logistics have already been thought through and completed. We simply have to trust the maker of the bridge (Christ being the bridge) that it won’t collapse as we walk over our flames of trials. This is why he finishes off this chapter with this… 19 Wherefore let them that suffer according to the will of God commit the keeping of their souls to him in well doing, as unto a faithful Creator."},{"kind":"para","text":"Trust the Creator because He is faithful. Trust Him in your suffering because He knows what He’s doing."}]}]}],"stories":[{"start":1,"end":1},{"start":12,"end":12}],"verses":{"1":"Forasmuch then as Christ hath suffered for us in the flesh, arm yourselves likewise with the same mind: for he that hath suffered in the flesh hath ceased from sin;","12":"Beloved, think it not strange concerning the fiery trial which is to try you, as though some strange thing happened unto you:"}},
    "5": {"chapter":5,"intro":[{"kind":"para","text":"Chapter: Chapter 05"},{"kind":"para","text":"Group: Tuesday"},{"kind":"para","text":"Status: Complete"},{"kind":"para","text":"Previously: This whole book at this point has been about trials and sufferings in the lives of Christians. Peter has been as encouraging as possible as he writes to these churches in hopes to help them continue for the faith. This last chapter closes up with some really important thoughts that will (hopefully) make an impact for any church that will suffer persecution and trials."}],"previously":["This whole letter at this point has been about trials and sufferings in the lives of Christians. Peter has been as encouraging as possible as he writes to these churches in hopes to help them continue in the faith. This last chapter closes up with some really important thoughts that will (hopefully) make an impact on any church that will suffer persecution and trials."],"outline":[],"sections":[{"start":1,"end":4,"title":"Suffering Produces Hope","entries":[{"start":1,"end":1,"blocks":[{"kind":"para","text":"Peter references himself as an “elder” here, putting himself on the same playing field as far as superiority. On a chess set, there are more pawns than there are any other category of player. The pawns don’t seem like much, but they take the lead as far as doing the king’s bidding. Their job is not to try and become a bishop or rook. Their job is to lead the charge and sacrifice themselves if need be so that they can protect the King."},{"kind":"para","text":"Peter isn’t about trying to overthrow any kind of authority in the churches that he is writing to. He is simply saying “I’m just as much in this as you are, and this is what I’ve learned from the trials that I have faced.” I have grown to really appreciate Peter’s humility towards his position in the Lord. Of all people, Peter would have the right to say that he is far better suited to be in charge, for not only did he see Christ’s suffering, but he was also COMMISSIONED by Christ AFTER denying Him three times."},{"kind":"para","text":"Paul says this about himself…"},{"kind":"scripture","text":"For I am the least of the apostles, that am not meet to be called an apostle, because I persecuted the church of God.","ref":"1 Corinthians 15:9"},{"kind":"para","text":"The only way to effectively lead through suffering is if you are humbled. 2 Feed the flock of God which is among you, taking the oversight thereof, not by constraint, but willingly; not for filthy lucre, but of a ready mind;"},{"kind":"para","text":"Interesting that Peter would use this terminology here."},{"kind":"scripture","text":"So when they had dined, Jesus saith to Simon Peter, Simon, son of Jonas, lovest thou me more than these? He saith unto him, Yea, Lord; thou knowest that I love thee. He saith unto him, Feed my lambs. He saith to him again the second time, Simon, son of Jonas, lovest thou me? He saith unto him, Yea, Lord; thou knowest that I love thee. He saith unto him, Feed my sheep. He saith unto him the third time, Simon, son of Jonas, lovest thou me? Peter was grieved because he said unto him the third time, Lovest thou me? And he said unto him, Lord, thou knowest all things; thou knowest that I love thee. Jesus saith unto him, Feed my sheep.","ref":"John 21:15-17"},{"kind":"para","text":"This is not just meant for Peter, and Peter understood this, which is why he’s telling the leaders of suffering churches to continue to feed the flock! You want to please God through your suffering? You want to know how to process the pain of trials? You want to know how to get joy out of a strenuous process of torment in this life? Feed God’s sheep."},{"kind":"para","text":"Don’t neglect telling others about the Word of God and helping them grow in their knowledge of His Word. This will bring you ultimate joy. It doesn’t have to be a lost person either. You can help those that are already saved, and when you are teaching them the things in which you have learned, it helps build YOU (the teacher) up as well. Peter’s joy through suffering was found by providing this edification to the churches he was writing to. Peter was going through a trial of suffering, and instead of guarding himself and hiding in the shadows of the church, he took the time to write to other suffering Christians to encourage them about HIS OWN suffering and how he’s able to process it. 3 Neither as being lords over God's heritage, but being examples to the flock."},{"kind":"para","text":"When we are placed in charge (by the Lord specifically) over a trial in our lives, (which we should be grateful that God has entrusted us with), then we should not be driving the flock. I know the best way to get the flock of sheep following is not by sitting on top of them or chasing them in the direction you want them to go. Rather, we are to stand ahead and lead them, keeping their eyes focused on greener pastures. Helping them to see the place they need to go for sustenance and provision. Driving the flock and leading the flock are two very different things. 4 And when the chief Shepherd shall appear, ye shall receive a crown of glory that fadeth not away."},{"kind":"para","text":"Many today are confused about the hierarchy of the church. They say, “What is an under shepherd? The Bible doesn’t speak about an ‘undershepherd.’” They are right. It doesn’t. However, the Bible does speak about a chief shepherd, and we are but elders (or under shepherds, as we are under the chief shepherd) of the flocks that ultimately belong to the Lord. You might ask, “So what does that mean? Does that mean we are in charge of the sheep and Christ is in charge of us?” No, and yes. I would say Christ is certainly in charge of us, but those who are elders, pastors, teachers, preachers, assistants, or any other type of leader in the church are just as much a sheep as the rest of the sheep. Someone said, “The congregation is not stupid. Sheep are not stupid. The pastor must not be afraid to smell like sheep.”"},{"kind":"para","text":"The work is ultimately for Him. Sometimes our rewards are not quite understood, and they certainly won’t always be instantaneous (nor should we want them to be, for our rewards given here will only stay here on Earth), but we should never be under the impression that our works are for nothing. If we are working for the Lord, the Lord is storing up for us treasures in Heaven that we will inherit in eternity. Those treasures will last forever, and those are the treasures we should desire when we get up there."},{"kind":"para","text":"The Chief Shepherd is the only one we have the work cut out for. He has given us approval to take care of and feed HIS flock. How we do that should be cautiously. Someone said, “The Good Shepherd gives His life for the sheep, which is seen in Psalm 22. The Great Shepherd watches over the sheep, which is seen in Psalm 23. The Chief Shepherd will be coming again to take His sheep, which is seen in Psalm 24.”"}]}]},{"start":5,"end":11,"title":"Suffering Produces humility and Patience","entries":[{"start":5,"end":6,"blocks":[{"kind":"para","text":"Important note: Peter was just speaking to the elders who were to watch over and feed the sheep of the Chief Shepherd. He seems to transition to the youngers now, but I don’t want this to be unnoticed. Though he starts off by speaking to the youngers here, he puts this in there so that we can remember that humility is bringing ourselves lower than those we think we are in charge of."},{"kind":"para","text":"Peter says, “ALL OF YOU be subject one to another, and be clothed with humility.” In other words, “Elders, be subject to the younger, and youngers be subject to the elders.” May we all remember that even the highest leaders in the church or anywhere in this world are still sheep. Ranking authority between sheep doesn’t make the lead sheep any less a sheep. It doesn’t cause the sheep to become a dog, or a human that will lead the rest. No, the lead sheep is still a sheep and needs the other sheep just as much as the other sheep need him. 7 Casting all your care upon him; for he careth for you. 8 Be sober, be vigilant; because your adversary the devil, as a roaring lion, walketh about, seeking whom he may devour: 9 Whom resist stedfast in the faith, knowing that the same afflictions are accomplished in your brethren that are in the world."},{"kind":"para","text":"This is another reminder of humility. If we are not careful, we can sometimes think we are doing quite alright. We think, “I’m quite the holy spectacle, and Satan has nothing to hold against me.” You usually don’t have to wait too long to see those who think that way buckle under the pressure of Satan. The reason that Satan has such a stronghold in those times is because we start leaning on ourselves rather than on the Lord."},{"kind":"para","text":"Trials and sufferings give us no choice but to either lean on the Lord or suffer under the weight ourselves. Usually, if we suffer under the weight on our own strength, we don’t come out on the other side. That’s why many take their lives because they just can’t handle the pressure anymore. It’s too much for them to bear. May we be cautious about thinking we are doing okay, lest we take our eyes off of Satan and are attacked because of our ignorance. 10 But the God of all grace, who hath called us unto his eternal glory by Christ Jesus, after that ye have suffered a while, make you perfect, stablish, strengthen, settle you."},{"kind":"para","text":"Take note. You won’t have strength, perfection, stability, or comfort, unless you first have suffering through your life with Christ. 11 To him be glory and dominion for ever and ever. Amen."},{"kind":"para","text":"This is Peter’s end to the letter on suffering. He finished his letter by reminding the church who deserves praise and glory. He wants to make sure the church understands that Christ is still in charge, and He knows all things that are taking place. Peter doesn’t want to quite end the letter yet, so he adds a P.S."}]}]},{"start":12,"end":14,"title":"Final Greetings","entries":[{"start":12,"end":12,"blocks":[{"kind":"para","text":"Obviously, Peter is the one that authored this letter, but it was apparently Silvanus that wrote it for him. McGee said, “If you don’t like the quality of the Greek here, blame Silvanus.” 13 The church that is at Babylon, elected together with you, saluteth you; and so doth Marcus my son."},{"kind":"para","text":"It’s supposed by some scholars that Peter was speaking about Rome when he mentions Babylon. Others assume he literally meant Babylon. I don’t really know which one he meant, but I do like the references to Marcus."},{"kind":"para","text":"This Marcus character is the same Marcus from the book of Acts, also known as John Mark. Most simply called him Mark, and he was the one with whom Paul had a serious issue because he didn’t continue with them on their missionary journeys. It’s worth the read in the book of Acts. Obviously, Peter has taken Mark under his wing and considers him to be his “Son in the Faith,” just like Paul considered Timothy to be HIS “Son in the Faith.” John (the Revelator), of course, (by his standards of consideration) one-ups each of them by calling his entire church his children in 1st, 2nd, and 3rd John. I digress. 14 Greet ye one another with a kiss of charity. Peace be with you all that are in Christ Jesus. Amen."},{"kind":"para","text":"A holy kiss is frowned upon today. Everyone’s too lustful and too loose. This wouldn’t be acceptable, and a simple handshake would suffice now. But the part that I think matters most about this verse is the final indication and remembrance that Peter leaves these suffering Christians with: peace. Peace."},{"kind":"scripture","text":"These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.","ref":"John 16:33"}]}]}],"stories":[{"start":1,"end":1},{"start":5,"end":6},{"start":12,"end":12}],"verses":{"1":"The elders which are among you I exhort, who am also an elder, and a witness of the sufferings of Christ, and also a partaker of the glory that shall be revealed:","5":"Likewise, ye younger, submit yourselves unto the elder. Yea, all of you be subject one to another, and be clothed with humility: for God resisteth the proud, and giveth grace to the humble.","6":"Humble yourselves therefore under the mighty hand of God, that he may exalt you in due time:","12":"By Silvanus, a faithful brother unto you, as I suppose, I have written briefly, exhorting, and testifying that this is the true grace of God wherein ye stand."}},
  },
};
